-- Who is connected and what are they doing?
SELECT pid, usename, state, wait_event_type, wait_event,
       now() - query_start AS running_for, left(query, 60) AS query
FROM pg_stat_activity
WHERE backend_type = 'client backend'
ORDER BY running_for DESC NULLS LAST;

-- How much memory is the shared cache using?
SHOW shared_buffers;   -- e.g. 128MB default
SHOW work_mem;         -- per sort/hash operation, NOT per connection total

-- How many connections are allowed?
SHOW max_connections;

-- WAL settings that govern durability and write throughput
SHOW wal_level;
SHOW max_wal_size;
SHOW synchronous_commit;
